  Kl = `(Beta) Hierbei handelt es sich um Seitenabrufe und Seitenaufrufe Ihrer Events und Ankündigungen durch eindeutige angemeldete Benutzer. Diese Zahlen werden nur für neue Events und Ankündigungen erfasst, die mit diesem Editor erstellt wurden.`,
