  hu = `Event-URL für Auswahl eingeben`,
  gu = `Geben Sie die vollständige Event-URL ein und wählen Sie dann aus dem Menü zur automatischen Vervollständigung aus. Das hinzuzufügende Event muss öffentlich sichtbar sein.`,
  _u = `Event erneut posten`,
  vu = `Erneut posten`,
  yu = `Beim erneuten Posten wird das Event erneut in der Zeitleiste im News-Hub der ausgewählten Gruppen unten angezeigt. Im Folgenden sind weitere Communitygruppen oder Anwendungen aufgeführt, für die dieses Event erneut veröffentlicht werden kann. Wählen Sie eine oder mehrere Gruppen aus, um das Event erneut zu posten.`,
