  Au = `Aufgeführter Inhalt: %2$s.`,
  ju = `Bevor diese Seite live geschaltet werden kann, muss diese von Valve überprüft werden.`,
  Mu = `Diese Rabattaktion wartet noch auf die Genehmigung von Valve.`,
  Nu = `Bitte reichen Sie Ihr Spiel mindestens sieben Tage vor Ihrem gewünschten Veröffentlichungsdatum zur Überprüfung ein. Nutzen Sie dafür die Schaltfläche auf der rechten Seite. Ein Zeitraum von mindestens sieben Tagen stellt sicher, dass genug Zeit für das Genehmigungsverfahren und ggf. für erforderliche Änderungen vorhanden ist.`,
  Pu = `Falls Änderungen an Ihrer Seite erforderlich sind, sendet Ihnen das Steam-Team ein Steamworks-Supportticket. Klicken Sie auf die Schaltfläche auf der rechten Seite, um Ihrem Ticket Kommentare hinzuzufügen.`,
  Fu = `Sobald Sie die Seite genehmigen, kann der Partner die Aktion veröffentlichen und live schalten.`,
  Iu = `Überprüfung anfordern\xA0…`,
  Lu = `Überprüfung anfordern`,
  Ru = `Fordert per Ticket die Überprüfung einer Aktionsseite zur Veröffentlichungsgenehmigung an. Fordern Sie diese erst an, wenn Ihre Aktionsseite über das endgültige Artwork verfügt und sämtliche Spiele, die Sie hervorheben möchten, eingebunden sind.`,
  zu = `Hierdurch wird eine Anfrage auf Überprüfung durch Valve an den Steamworks-Support gesendet. Reichen Sie Ihre Seite erst dann zur Überprüfung ein, wenn Ihre Grafiken und Ihre Texte festgelegt sind und die Liste der Spiele vollständig ist.`,
  Bu = `Bitte stellen Sie sicher, dass der Titel und das Ziel Ihrer Aktion oben auf der Seite klar beschrieben sind. Dies gilt ggf. auch für Aktions- bzw Startseiten für Festivals und Messen. Erläutern Sie oben auf Ihrer Seite die Art Ihrer Teilnahme und präsentierten Inhalte.`,
  Vu = `Sobald die Aktionsseite geprüft wurde, wird sie gesperrt. Falls Sie nach der Prüfung oder zu Beginn des Events Änderungen vornehmen müssen, erläutern Sie bitte im Kommentarfeld, welche Änderungen nötig sind und warum Sie diese nicht vor der Prüfung abschließen konnten.`,
  Hu = `Optional: Informationen für die Überprüfer`,
  Uu = `Gewähren Sie Partnern Zugriff auf die Anfrage`,
  Wu = `Optional: Falls Sie diese Option auswählen, können Mitglieder der aufgeführten Partner ebenfalls auf das Ticket zugreifen und darauf reagieren. Standardmäßig können nur Sie das erstellte Ticket lesen, aktualisieren und darauf reagieren.`,
  Gu = `Ticket konnte nicht erstellt werden. Bitte versuchen Sie es später erneut.`,
  Ku = `Es konnte kein neues Ticket erstellt werden, da bereits ein Ticket dieses Typs existiert. Bitte vervollständigen Sie den Überprüfungsprozess für Ihre andere Aktionsseite, bevor Sie ein neues Ticket einsenden, oder aktualisieren Sie das bestehende Ticket, damit diese Seite ebenfalls in die Überprüfung einbezogen wird.`,
  qu = `Ticket wurde erfolgreich erstellt!`,
  Ju = `Überprüfungsticket anzeigen\xA0…`,
  Yu = `Ihre Seite wurde genehmigt und kann veröffentlicht werden.`,
  Xu = `Wechseln Sie für den Veröffentlichungsprozess zum Tab „Veröffentlichen“.`,
  Zu = `Überprüfen Sie vor der Veröffentlichung Ihre Sichtbarkeitseinstellungen.`,
