  cS = `Wählen Sie einen ansprechenden Titel, der für Spieler relevant ist. Wenn es sich um eines der größten Updates des Jahres handelt, sollte der Titel entsprechende Begeisterung ausdrücken. Vermeiden Sie allgemeine Formulierungen wie <1>„Update Version 330.4“.</1> Heben Sie stattdessen die Besonderheiten des Updates hervor.`,
  lS = `Die wichtigsten Grafiken müssen die Inhalte des Updates widerspiegeln. Verwenden Sie daher nicht die Standardgrafiken Ihres Spiels. Spieler sollten sofort erkennen können, dass es sich um bedeutende Änderungen und/oder Neuerungen handelt.`,
