  bV = `Zurücklehnen und entspannen`,
  xV = `Schlagen Sie keine bestimmte Kategorie vor, sondern überlassen Sie die Wahl Ihren Fans! Das Event fügt nichtsdestotrotz einen Link zur Nominierungsseite ein.`,
  SV = `Keine Kategorie`,
  CV = `Vielleicht war es das immersive Gameplay oder die packende Geschichte, die gut gestalteten Charaktere, ein makelloses Design oder ein süchtig machender Mehrspielermodus. Wie dem auch sei, der Gewinner des diesjährigen Preises für das Spiel des Jahres 2020 hat sich sofort als Klassiker etabliert.`,
  wV = `Das VR-Spiel des Jahres tarnt sich nicht einfach als normale Realität. Dieses Spiel verbessert die Realität, nutzt das Medium VR und überschreitet die Grenzen virtueller Erlebnisse.`,
  TV = `Dieses Spiel ist bereits seit einer ganzen Weile auf dem Markt. Das Entwicklerteam hat den Schleier seines kreativen Schatzes längst gelüftet, doch als gute Eltern feilen sie noch immer an ihrer Kreation. Dieses Spiel wird bis heute unterstützt und bekommt nach all den Jahren noch immer neue Inhalte.`,
  EV = `Es gibt Spiele, die ein besseres Erlebnis bieten, wenn man sie nicht allein spielt. Vielleicht brauchen Sie einen Freund, der Ihnen den Rücken freihält. Vielleicht haben Sie einen Freund, dem Sie einen Dolch in den Rücken stoßen möchten. Wie dem auch sei, wenn man diese Spiele mit Freunden spielt, ist Freude vorprogrammiert.`,
  DV = `Der visuelle Stil versucht nicht die grafische Auflösung der Realität einzufangen (obwohl das durchaus ein nobles Unterfangen ist), sondern verfügt über ein einzigartiges Aussehen und eine besondere Atmosphäre, die sich durch das gesamte Spiel ziehen.`,
  OV = `Die Designer dieses Spiels zählen zur Avantgarde kreativer Experimente. Sie zeigen neue Perspektiven und Gehirn-verknotende Überraschungen. Dieses Spiel bringt Freude, Inspiration und erstaunt mit einem unvergleichlichen Spielerlebnis.`,
  kV = `Dieses Spiel belohnt Beharrlichkeit und ist nichts für schwache Nerven. Es ist das härteste Spiel, das wir je geliebt haben.`,
  AV = `Dieser unbesungene Held verdient es, für seine herausragende musikalische Leistung anerkannt zu werden. `,
  jV = `An manchen Tagen tut es nur ein Spiel mit tiefgründiger Story und dieses Spiel ist Story pur. So ergreifend wie eine Seifenoper, so fein abgestimmt wie ein Prestige-Fernsehfilm\xA0–\xA0Hut ab! Wir fühlen mit!`,
  MV = `Dieses Spiel ist die beste Medizin für arbeitsreiche Tage. Der Geist entspannt, die Sorgen schmelzen – das perfekte Zen-Erlebnis.`,
  NV = `Sie möchten Ihre Nominierung ändern?`,
  PV = `Es kann nur ein Spiel pro Kategorie nominiert werden und Sie haben bereits %1$s für diese Kategorie nominiert. Möchten Sie Ihre Wahl ändern und stattdessen %2$s nominieren?`,
  FV = `Abstimmen`,
