  zV = `Es kann nur für ein Spiel pro Kategorie abgestimmt werden und Sie haben bereits %1$s Ihre Stimme für diese Kategorie gegeben. Möchten Sie Ihre Stimme ändern und stattdessen %2$s geben?`,
  BV = `Anscheinend ist Ihr Account eingeschränkt. Um den Missbrauch bei Nominierungen zu vermeiden, müssen Sie 5 US-Dollar auf Steam ausgeben, um an den Steam Awards teilnehmen zu können. Sie benötigen weitere Informationen? %1$s.`,
  VV = `Anscheinend ist Ihr Account eingeschränkt. Um den Missbrauch bei Abstimmungen zu vermeiden, müssen Sie 5 US-Dollar auf Steam ausgeben, um an den Steam Awards teilnehmen zu können. Sie benötigen weitere Informationen? %1$s.`,
