  nH = `Der visuelle Stil versucht nicht die grafische Auflösung der Realität einzufangen (obwohl das durchaus ein nobles Unterfangen ist), sondern verfügt über ein einzigartiges Aussehen und eine besondere Atmosphäre, die sich durch das gesamte Spiel ziehen.`,
  rH = `Die Designer dieses Spiels zählen zur Avantgarde kreativer Experimente. Sie zeigen neue Perspektiven und Gehirn-verknotende Überraschungen. Dieses Spiel bringt Freude, Inspiration und erstaunt mit einem unvergleichlichen Spielerlebnis.`,
