  xH = `Dieses Spiel ist bereits seit einer ganzen Weile auf dem Markt. Das Entwicklerteam hat den Schleier seines kreativen Schatzes längst gelüftet, doch als gute Eltern feilen sie noch immer an ihrer Kreation. Dieses Spiel wird bis heute unterstützt und bekommt nach all den Jahren noch immer neue Inhalte.`,
  SH = `Es gibt Spiele, die ein besseres Erlebnis bieten, wenn man sie nicht allein spielt. Vielleicht brauchen Sie einen Freund, der Ihnen den Rücken freihält. Vielleicht haben Sie einen Freund, dem Sie einen Dolch in den Rücken stoßen möchten. Wie dem auch sei, wenn man diese Spiele mit Freunden spielt, ist Freude vorprogrammiert.`,
  CH = `Der visuelle Stil versucht nicht die grafische Auflösung der Realität einzufangen (obwohl das durchaus ein nobles Unterfangen ist), sondern verfügt über ein einzigartiges Aussehen und eine besondere Atmosphäre, die sich durch das gesamte Spiel ziehen.`,
  wH = `Die Designer dieses Spiels zählen zur Avantgarde kreativer Experimente. Sie zeigen neue Perspektiven und Gehirn-verknotende Überraschungen. Dieses Spiel bringt Freude, Inspiration und erstaunt mit einem unvergleichlichen Spielerlebnis.`,
  TH = `Dieses Spiel belohnt Beharrlichkeit und ist nichts für schwache Nerven. Es ist das härteste Spiel, das wir je geliebt haben.`,
  EH = `Dieser unbesungene Held verdient es, für seine herausragende musikalische Leistung anerkannt zu werden! `,
  DH = `An manchen Tagen tut es nur ein Spiel mit tiefgründiger Story und dieses Spiel ist Story pur. So ergreifend wie eine Seifenoper, so fein abgestimmt wie ein Prestige-Fernsehfilm\xA0–\xA0Hut ab! Wir fühlen mit!`,
  OH = `Dieses Spiel ist die beste Medizin für arbeitsreiche Tage. Der Geist entspannt, die Sorgen schmelzen – das perfekte Zen-Erlebnis.`,
  kH = `Dieses Spiel ist so gut, dass Sie es überallhin mitnehmen wollten. Was Sie auch getan haben. Und glücklicherweise war das, was am Schreibtisch endlos viel Spaß gemacht hat, unterwegs sogar noch besser.`,
  AH = `Nur VR`,
  jH = `VR-Unterstützung`,
  MH = `Noch %1$s bis zur nächsten Auslosung!`,
  NH = `Verbleibende Zeit bis zur nächsten Auslosung.`,
