  YH = `nächstes öffnen`,
  XH = `am %1$s öffnen`,
  ZH = `Bitte verwenden Sie einen Browser, der HTML-Videos unterstützt, um Ihren Umschlag zu öffnen.`,
  QH = `Zurück zur Rabattaktion`,
  $H = `Zum Markt`,
  eU = `Sie haben %1$s Marken erhalten`,
  tU = `Ihre Marken`,
  nU = `%1$s Marken`,
  rU = `Umschlag konnte nicht geöffnet werden`,
  iU = `DAS GROSSE RENNEN DES KAISERS`,
  aU = `Der Ursprung der chinesischen Tierkreiszeichen`,
  oU = `TEIL I VON IV`,
  sU = `TEIL II VON IV`,
  cU = `TEIL III VON IV`,
  lU = `TEIL IV VON IV`,
  uU = `Der Jadekaiser rief alle Kreaturen seines Königreichs dazu auf, am Rennen zum himmlischen Palast teilzunehmen, um sich einen Platz in seinem neuen Kalender als einer der ersten zwölf Ankömmlinge zu verdienen.

Die schlaue Ratte erreichte als Erstes die himmlische Ebene. Schwimmen war allgemein überbewertet, daher überließ sie es dem Ochsen und ritt auf dessen Rücken. Sekunden bevor dieser das Ufer erreichte, sprang sie in den himmlischen Garten des Kaisers.

Der Ochse war am Ergebnis des Rennens nicht sonderlich interessiert und ließ sich beim Überqueren Zeit. Den ersten Platz wollte er der Ratte gern überlassen.`,
  dU = `Der eigenständige Tiger bewegte sich zu vorsichtig, als dass er den Ochsen hätte überholen können. Besser auf dem 3. Platz landen, als auf gar keinem.

Der flinke Hase schwamm in Seelenruhe den Fluss entlang. Zwar ging diese Strategie nicht auf, aber ein günstiger Wind gab ihm den nötigen Schub in die richtige Richtung.

Der Gipfel des fliegenden Drachen zeigte ihm Andere in Schwierigkeiten und er half allen, auch dem Hasen. Was ist ein 5. Platz in einem Rennen, wenn es um die Ehre geht?`,
  fU = `Die verstohlene Schlange hatte an einem Langstreckenlauf auch kein Interesse, also wickelte sie sich um den Huf des Pferdes.

Als dieses die Ziellinie fast erreicht hatte, glitt sie zu Boden und erschreckte das Pferd dadurch so sehr, dass sie es noch gerade auf den 6. Platz schaffte, mit dem Pferd hintendrein.`,
  pU = `Ziege, Affe und Hahn vertrauten auf Teamarbeit, überließen Ziege aber als Rückgrat des Teams den 8. Platz. Der fröhliche Affe gelangte verdient auf den 9. Platz und Hahn stolzierte auf Platz 10 über die Ziellinie, zufrieden damit, dass alles fair lief.

Der verspielte Hund wollte eigentlich nur herumplanschen und hielt den 11. Platz für einen fairen Tausch für mehr Schwimmspaß.

An 12. Stelle kam Schwein, das eine kurze Verdauungspause eingelegt hatte\xA0– wohlwissend, dass jedes Tier eine Audienz beim Kaiser erhält.`,
