  Ufe = `Anonymisierte Daten zur Bildrate:`,
  Wfe = `Anonymisierte Daten zur Bildrate`,
  Gfe = `Gestatten Sie Steam, während des Spielens sowie der aktiven Nutzung des Steam-Accounts anonyme Daten zur Bildrate zu sammeln? Diese Daten werden zur Kompatibilitätsprüfung von Spielen sowie zur Verbesserung von Steam verwendet.`,
  Kfe = `Anonymisierte Daten zur Bildrate`,
  qfe = `Durch die Aktivierung dieser Option, werden beim Spielen Daten zur Bildrate erfasst und gespeichert. Diese Daten enthalten keine accountbezogenen Informationen, geben jedoch Aufschluss darüber, welche Hardware zum Spielen verwendet wurde. Die Erfassung dieser Daten gibt Steam Aufschluss über die Kompatibilität von Spielen und trägt so zur Verbesserung der allgemeinen Spielerfahrung auf Geräten mit Steam bei.`,
  Jfe = `Sie können diese Einstellung jederzeit unter <1>Accountdetails > Daten und Browsernutzung</1> ändern.`,
  Yfe = `Mehr erfahren`,
  Xfe = `Steam-Deck-Kompatibilität`,
  Zfe = `Für das Steam Deck verifiziert\xA0– Kundenfeedback`,
  Qfe = `Keine Daten verfügbar`,
  $fe = `%1$s der Befragten stimmen der Bewertung „%2$s“ für dieses Spiel zu.`,
  epe = `Zum Vergleich: Die durchschnittliche Zustimmungsrate aller für das Steam Deck verifizierten Spiele liegt bei %1$s.`,
  tpe = `%1$s %`,
  npe = `Wir stellen diese Daten zur Verfügung, da Kunden zwar überwiegend der Bewertung der Steam-Deck-Kompatibilitätsprüfung zustimmen (über %1$s %), es aber für Entwickler wertvoll sein kann, die Erfahrungen von Kunden, die anderer Meinung sind, besser zu verstehen, insbesondere im Zusammenhang mit einem bestimmten Titel oder Update.`,
  rpe = `Leistung`,
  ipe = `Lesbarkeit`,
  ape = `Stabilität`,
  ope = `Eingabe`,
  spe = `Andere Gründe`,
  cpe = `Diese Daten basieren auf %1$s Meldungen der letzten %2$s Tage von Kunden, die sich dazu bereit erklärt haben, Feedback zum Steam Deck zu hinterlassen.`,
  lpe = `Kunden, die dem Status „%2$s“ des Spiels %1$s, gaben folgende Gründe dafür an:`,
  upe = `nicht zustimmten`,
  dpe = `Daten zur Bildrate des Steam Deck`,
  fpe = `Durchschnittliche Steam-Deck-Bildrate`,
  ppe = `Die durchschnittlich gemeldete Bildrate für %1$s auf %2$s beträgt %3$s`,
  mpe = `Die durchschnittlich gemeldete Bildrate für dieses Spiel auf %1$s beträgt %2$s`,
  hpe = `%1$s\xA0FPS`,
  gpe = `Die Daten zur Bildrate des Steam Deck basieren auf Meldungen im Zeitraum von %1$s Tagen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate ihres Geräts zu teilen.`,
  _pe = `Die Daten zur Bildrate des Steam Deck basieren auf Meldungen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate ihres Geräts zu teilen.`,
  vpe = `Hinweis: Die Varianz wird derzeit nicht angezeigt, ist aber für die Beta-Phase geplant. Mithilfe der Varianzdaten können Sie erkennen, ob die Bildrate konstant ist oder stark schwankt.`,
